# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Kernel: one block per row, computes cross-entropy loss for that row
// Stores per-row loss into losses[row]
__global__ void cross_entropy_row_kernel(
    const float* __restrict__ predictions,
    const int64_t* __restrict__ targets,
    float* __restrict__ losses,
    int N,
    int C
) {
    int row = blockIdx.x;
    if (row >= N) return;

    const float* row_ptr = predictions + row * C;
    int64_t target = targets[row];

    // Step 1: find row max
    float row_max = -1e38f;
    for (int j = threadIdx.x; j < C; j += blockDim.x) {
        float val = row_ptr[j];
        if (val > row_max) row_max = val;
    }

    // Reduce max across threads using shared memory
    extern __shared__ float smem[];
    smem[threadIdx.x] = row_max;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            if (smem[threadIdx.x + stride] > smem[threadIdx.x])
                smem[threadIdx.x] = smem[threadIdx.x + stride];
        }
        __syncthreads();
    }
    row_max = smem[0];
    __syncthreads();

    // Step 2: compute sum(exp(x - max))
    float sum_exp = 0.0f;
    for (int j = threadIdx.x; j < C; j += blockDim.x) {
        sum_exp += expf(row_ptr[j] - row_max);
    }

    smem[threadIdx.x] = sum_exp;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        }
        __syncthreads();
    }
    sum_exp = smem[0];

    // Step 3: compute loss for this row
    if (threadIdx.x == 0) {
        float target_logit = row_ptr[target];
        float loss = logf(sum_exp) - (target_logit - row_max);
        losses[row] = loss;
    }
}

// Kernel: reduce N losses to a scalar mean
__global__ void reduce_mean_kernel(
    const float* __restrict__ losses,
    float* __restrict__ output,
    int N
) {
    extern __shared__ float smem[];
    float sum = 0.0f;
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        sum += losses[i];
    }
    smem[threadIdx.x] = sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            smem[threadIdx.x] += smem[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        output[0] = smem[0] / (float)N;
    }
}

torch::Tensor cross_entropy_forward_cuda(torch::Tensor predictions, torch::Tensor targets) {
    int N = predictions.size(0);
    int C = predictions.size(1);

    // Convert to float32 if needed
    torch::Tensor pred_f32;
    if (predictions.dtype() == torch::kFloat16) {
        pred_f32 = predictions.to(torch::kFloat32);
    } else {
        pred_f32 = predictions;
    }

    // Allocate per-row losses
    auto losses = torch::empty({N}, torch::TensorOptions().dtype(torch::kFloat32).device(predictions.device()));
    auto output = torch::empty({1}, torch::TensorOptions().dtype(torch::kFloat32).device(predictions.device()));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    int block_size = 256;
    size_t smem_size = block_size * sizeof(float);

    cross_entropy_row_kernel<<<N, block_size, smem_size, stream>>>(
        pred_f32.data_ptr<float>(),
        targets.data_ptr<int64_t>(),
        losses.data_ptr<float>(),
        N,
        C
    );

    int reduce_block = 256;
    if (reduce_block > N) reduce_block = 1;
    // Round up to power of 2
    int rb = 1;
    while (rb < reduce_block) rb <<= 1;
    reduce_block = rb;
    if (reduce_block < 1) reduce_block = 1;

    reduce_mean_kernel<<<1, reduce_block, reduce_block * sizeof(float), stream>>>(
        losses.data_ptr<float>(),
        output.data_ptr<float>(),
        N
    );

    // Return scalar with same dtype as predictions
    auto result = output[0];
    if (predictions.dtype() == torch::kFloat16) {
        return result.to(torch::kFloat16);
    }
    return result;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that computes Cross Entropy Loss for multi-class classification tasks.

        Parameters:
            None
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, predictions, targets):
        # <<<IMPROVE:forward_stmt_1>>>
        if (predictions.is_cuda and targets.is_cuda and
                predictions.dim() == 2 and targets.dim() == 1 and
                predictions.size(0) == targets.size(0) and
                predictions.numel() > 0 and
                predictions.is_contiguous() and targets.is_contiguous() and
                targets.dtype == torch.long and
                predictions.dtype in (torch.float16, torch.float32)):
            return _stark_get_extension().cross_entropy_forward(predictions, targets)
        return torch.nn.functional.cross_entropy(predictions, targets)
        # <<<END_IMPROVE>>>

